"""Seed data for the stitch glossary: US abbreviation, UK abbreviation, name, how to do it."""

STITCHES = [
    ("ch", "ch", "Chain", "Yarn over and pull through the loop on your hook."),
    ("sl st", "ss", "Slip stitch", "Insert hook, yarn over, pull through the stitch and the loop on your hook in one go."),
    ("sc", "dc", "Single crochet", "Insert hook, yarn over, pull up a loop (2 loops on hook), yarn over, pull through both."),
    ("hdc", "htr", "Half double crochet", "Yarn over, insert hook, pull up a loop (3 loops), yarn over, pull through all three."),
    ("dc", "tr", "Double crochet", "Yarn over, insert hook, pull up a loop (3 loops), [yarn over, pull through 2] twice."),
    ("tr", "dtr", "Treble crochet", "Yarn over twice, insert hook, pull up a loop (4 loops), [yarn over, pull through 2] three times."),
    ("dtr", "ttr", "Double treble crochet", "Yarn over three times, insert hook, pull up a loop, then [yarn over, pull through 2] four times."),
    ("inc", "inc", "Increase", "Work 2 stitches into the same stitch."),
    ("dec", "dec", "Decrease", "Work 2 stitches together so they become one (for sc: sc2tog)."),
    ("sc2tog", "dc2tog", "Single crochet 2 together", "Insert in next st, pull up a loop; insert in the one after, pull up a loop (3 loops); yarn over, pull through all."),
    ("dc2tog", "tr2tog", "Double crochet 2 together", "Work a dc up to the last pull-through in each of 2 stitches (3 loops), yarn over, pull through all."),
    ("inv dec", "inv dec", "Invisible decrease", "Insert hook in the front loops only of the next 2 stitches, yarn over, pull through both front loops, yarn over, pull through 2. Neat for amigurumi."),
    ("MR", "MR", "Magic ring", "Wrap yarn around your fingers to form a loop, work the first round into it, then pull the tail to close the hole."),
    ("BLO", "BLO", "Back loop only", "Work into just the loop furthest from you. Leaves a ridge on the front."),
    ("FLO", "FLO", "Front loop only", "Work into just the loop closest to you."),
    ("FPdc", "FPtr", "Front post double crochet", "Yarn over, insert hook from front to back to front around the post (the stem) of the stitch, then finish as a dc."),
    ("BPdc", "BPtr", "Back post double crochet", "Yarn over, insert hook from back to front to back around the post of the stitch, then finish as a dc."),
    ("st", "st", "Stitch", "One stitch; sts means stitches."),
    ("sk", "miss", "Skip", "Don't work into the next stitch(es); move past them."),
    ("yo", "yrh", "Yarn over", "Wrap the yarn over the hook from back to front."),
    ("tog", "tog", "Together", "Work the stitches together into one (as in sc2tog)."),
    ("rep", "rep", "Repeat", "Do the instructions again, usually the part in brackets or between asterisks."),
    ("rnd", "rnd", "Round", "One trip around when working in the round."),
    ("sp", "sp", "Space", "The gap between stitches or under a chain; work into the space, not a stitch."),
    ("tch", "tch", "Turning chain", "Chains made at the start of a row to reach the height of the next stitches."),
    ("RS", "RS", "Right side", "The side that will show."),
    ("WS", "WS", "Wrong side", "The back of the work."),
    ("FO", "FO", "Fasten off", "Cut the yarn, leaving a tail, and pull it through the last loop to lock it."),
    ("pm", "pm", "Place marker", "Clip a stitch marker into the stitch, usually the first of the round."),
    ("fsc", "fdc", "Foundation single crochet", "Makes the chain and first row of sc at the same time, so the edge is stretchy."),
    ("rev sc", "crab st", "Reverse single crochet (crab stitch)", "Single crochet worked backwards (left to right for right-handers) for a corded edge."),
    ("V-st", "V-st", "V-stitch", "(dc, ch 1, dc) all in the same stitch or space."),
    ("shell", "shell", "Shell", "Several tall stitches (often 5 dc) in the same stitch, fanning out."),
    ("cl", "cl", "Cluster", "Several part-finished stitches joined at the top with one pull-through."),
    ("bobble", "bobble", "Bobble", "Several part-finished dc in one stitch, joined at the top, which pops out as a bump."),
    ("puff", "puff", "Puff stitch", "[Yarn over, insert, pull up a long loop] several times in one stitch, then yarn over and pull through all."),
    ("picot", "picot", "Picot", "Chain 3, then slip stitch into the first chain to make a little point."),
    ("popcorn", "popcorn", "Popcorn", "Several dc in one stitch; drop the loop, insert in the first dc, pick up the loop and pull it through."),
]
